def _список_домерить():
    return []


def поле(d, ключ, метка, недомеры):
    v = d.get(ключ) if isinstance(d, dict) else None
    if v is None or (isinstance(v, str) and not v.strip()):
        недомеры.append(метка)
        return ПУСТО
    return v


def _границы_таблицы(table):
    tblPr = table._tbl.tblPr
    borders = OxmlElement("w:tblBorders")
    for edge in ("top", "left", "bottom", "right", "insideH", "insideV"):
        el = OxmlElement(f"w:{edge}")
        el.set(qn("w:val"), "single")
        el.set(qn("w:sz"), "4")
        el.set(qn("w:color"), "000000")
        borders.append(el)
    tblPr.append(borders)


def _снять_границы(table):
    tblPr = table._tbl.tblPr
    for b in tblPr.findall(qn("w:tblBorders")):
        tblPr.remove(b)
    borders = OxmlElement("w:tblBorders")
    for edge in ("top", "left", "bottom", "right", "insideH", "insideV"):
        el = OxmlElement(f"w:{edge}")
        el.set(qn("w:val"), "none")
        borders.append(el)
    tblPr.append(borders)


def ячейка(cell, текст, bold=False, center=False, size=10):
    cell.text = ""
    for i, часть in enumerate(str(текст).split("\n")):
        p = cell.paragraphs[0] if i == 0 else cell.add_paragraph()
        if center:
            p.alignment = WD_ALIGN_PARAGRAPH.CENTER
        run = p.add_run(часть)
        run.font.name = "Times New Roman"
        run.font.size = Pt(size)
        run.bold = bold
        rPr = run._element.get_or_add_rPr()
        rFonts = rPr.find(qn("w:rFonts"))
        if rFonts is None:
            rFonts = OxmlElement("w:rFonts")
            rPr.append(rFonts)
        rFonts.set(qn("w:cs"), "Times New Roman")


def параграф(doc, текст, bold=False, center=False, size=11, justify=True,
             space_after=6):
    p = doc.add_paragraph()
    if center:
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    elif justify:
        p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    p.paragraph_format.space_after = Pt(space_after)
    run = p.add_run(текст)
    run.font.name = "Times New Roman"
    run.font.size = Pt(size)
    run.bold = bold
    return p


def таблица(doc, rows, cols, границы=True):
    t = doc.add_table(rows=rows, cols=cols)
    t.alignment = WD_TABLE_ALIGNMENT.CENTER
    if границы:
        _границы_таблицы(t)
    return t


def _новый_документ():
    doc = Document()
    стиль = doc.styles["Normal"]
    стиль.font.name = "Times New Roman"
    стиль.font.size = Pt(11)
    for sec in doc.sections:
        sec.left_margin = Cm(2)
        sec.right_margin = Cm(1.5)
        sec.top_margin = Cm(2)
        sec.bottom_margin = Cm(2)
    return doc


def _раздел_домерить(doc, недомеры):
    if not недомеры:
        return
    doc.add_page_break()
    параграф(doc, "Поля, требующие заполнения («домерить»)", bold=True,
             size=12, justify=False)
    уник = []
    for м in недомеры:
        if м not in уник:
            уник.append(м)
    for м in уник:
        параграф(doc, "– " + м, justify=False, space_after=2, size=10)


# ---------------------------------------------------------------------------
# АКТ НАЧАЛА МЕРОПРИЯТИЙ (Приложение № 7 к Соглашению)
# ---------------------------------------------------------------------------

НАЦПРОЕКТ_РЦК = ("«Производительность труда»")
НАЦПРОЕКТ_ФЦК = ("«Производительность труда и поддержка занятости»")


def build_akt(d, путь_выход):
    """Акт начала мероприятий. Варианты: «рцк» (форма из соглашения ред. 8)
    и «фцк» (Приложение № 7 к Соглашению ФЦК-предприятие)."""
    if not isinstance(d, dict):
        raise ValueError("Корень вход-JSON должен быть объектом")
    недомеры = []
    вариант = (d.get("вариант") or "рцк").strip().lower()
    if вариант not in ("рцк", "фцк"):
        raise ValueError("поле «вариант» должно быть «рцк» или «фцк»")
    фцк = вариант == "фцк"
    центр_имя = ("Автономная некоммерческая организация «Федеральный центр "
                 "компетенций в сфере производительности труда»" if фцк else
                 (d.get("центр") or ПУСТО))
    if not фцк and not (d.get("центр") or "").strip():
        недомеры.append("Наименование РЦК")
    центр_кратко = "Федеральный Центр Компетенций" if фцк else "РЦК"
    пр = поле(d, "предприятие", "Акт: предприятие", недомеры)
    город = поле(d, "город", "Акт: город подписания", недомеры)
    дата_акта = поле(d, "дата_акта", "Акт: дата акта", недомеры)
    согл = d.get("соглашение") or {}
    дата_согл = поле(согл, "дата", "Акт: дата соглашения", недомеры)
    дата_нач = поле(d, "дата_начала", "Акт: дата начала мероприятий", недомеры)
    подп = d.get("подписанты") or {}
    пп, пц = подп.get("предприятие") or {}, подп.get("центр") or {}
    for блок, имя in ((пп, "Подписант от Предприятия"), (пц, "Подписант от Центра")):
        if not блок.get("должность") or not блок.get("фио"):
            недомеры.append(имя + ": должность и ФИО")
    нац = НАЦПРОЕКТ_ФЦК if фцк else НАЦПРОЕКТ_РЦК

    doc = _новый_документ()
    параграф(doc, "Приложение № 7", justify=False, space_after=0, size=10)
    номер = (согл.get("номер") or "").strip()
    if номер:
        параграф(doc, f"к Соглашению о сотрудничестве № {номер} от {дата_согл}",
                 justify=False, space_after=0, size=10)
    параграф(doc, "_" * 34 + "ФОРМА" + "_" * 34, center=True, justify=False,
             size=9, space_after=10)
    параграф(doc, "АКТ НАЧАЛА МЕРОПРИЯТИЙ", bold=True, center=True, size=14,
             justify=False, space_after=10)
    t = таблица(doc, 1, 2, границы=False)
    _снять_границы(t)
    ячейка(t.rows[0].cells[0], город, center=True)
    ячейка(t.rows[0].cells[1], дата_акта, center=True)
    параграф(doc, "")
    параграф(doc,
        f"Между {центр_имя} (далее – {центр_кратко}) и {пр} "
        f"(далее - Предприятие) заключено Соглашение о сотрудничестве в целях "
        f"реализации национального проекта {нац}, федерального и регионального "
        f"проектов «Адресная поддержка повышения производительности труда на "
        f"предприятиях» от {дата_согл} (далее – Соглашение о сотрудничестве).")
    параграф(doc,
        f"Подписанием настоящего акта {центр_кратко} и Предприятие "
        f"согласовали, что датой начала Мероприятий в соответствии с п. 1.4. "
        f"Соглашения о сотрудничестве является {дата_нач}.")
    параграф(doc,
        f"{центр_кратко} и Предприятие подтверждают свои намерения по "
        f"исполнению условий и достижению целей Соглашения о сотрудничестве "
        f"в полном объеме.")
    if not фцк:
        отв = d.get("ответственный_центра")
        if not (отв or "").strip():
            отв = ПУСТО
            недомеры.append("Акт: ответственное лицо РЦК (п. 2.2.1 Соглашения)")
        параграф(doc,
            f"В соответствии с п. 2.2.1. Соглашения о сотрудничестве лицо, "
            f"ответственное за осуществление взаимодействия с Предприятием "
            f"в ходе проведения Мероприятий — {отв}.")
    параграф(doc,
        f"Настоящий акт составлен в двух экземплярах, имеющих одинаковую "
        f"юридическую силу, один из которых передается Предприятию, "
        f"второй – {центр_кратко}му Центру Компетенций." if фцк else
        f"Настоящий акт составлен в двух экземплярах, имеющих одинаковую "
        f"юридическую силу, один из которых передается Предприятию, "
        f"второй – РЦК.")
    параграф(doc, "")
    for заголовок, блок in (("От Предприятия:", пп),
                            (f"От {центр_кратко}:", пц)):
        параграф(doc, заголовок, bold=True, justify=False, space_after=2)
        t = таблица(doc, 2, 3, границы=False)
        _снять_границы(t)
        r = t.rows[0].cells
        ячейка(r[0], "_" * 15, center=True)
        ячейка(r[1], "_" * 15, center=True)
        ячейка(r[2], "_" * 19, center=True)
        r = t.rows[1].cells
        ячейка(r[0], блок.get("должность") or "должность", center=True, size=9)
        ячейка(r[1], "подпись", center=True, size=9)
        ячейка(r[2], блок.get("фио") or "фамилия, инициалы", center=True, size=9)
        параграф(doc, "М.П.", justify=False, space_after=10)
    параграф(doc, "_" * 33 + "ФОРМУ УТВЕРЖДАЕМ:" + "_" * 33, center=True,
             justify=False, size=9, space_after=10)
    t = таблица(doc, 2, 2, границы=False)
    _снять_границы(t)
    ячейка(t.rows[0].cells[0], "от Предприятия:", bold=True)
    ячейка(t.rows[0].cells[1], f"от {центр_кратко}:", bold=True)
    ячейка(t.rows[1].cells[0],
           "_____________________ /%s/\nМ.П." % (пп.get("фио") or "___"))
    ячейка(t.rows[1].cells[1],
           "_____________________ /%s/\nМ.П." % (пц.get("фио") or "___"))
    _раздел_домерить(doc, недомеры)
    doc.save(путь_выход)
    return {"вариант": вариант, "незаполненных_полей": len(set(недомеры)),
            "путь": путь_выход}


# ---------------------------------------------------------------------------
# СОГЛАШЕНИЕ О СОТРУДНИЧЕСТВЕ (рекомендованная форма ред. 8)
# ---------------------------------------------------------------------------

def _подстановки(d, недомеры):
    """Карта точных замен по тексту скелета. Ключ — дословный текст шаблона,
    значение — заполненный текст (порядок повторов учитывается отдельно)."""
    увед = d.get("уведомления") or {}
    уп, уц = увед.get("предприятие") or {}, увед.get("рцк") or {}
    рек = d.get("реквизиты") or {}
    рп, рц = рек.get("предприятие") or {}, рек.get("рцк") or {}
    номер = (d.get("номер") or "").strip() or "_______"
    if номер == "_______":
        недомеры.append("Соглашение: номер")
    пр = поле(d, "предприятие", "Соглашение: предприятие", недомеры)
    рцк = поле(d, "рцк", "Соглашение: наименование РЦК", недомеры)
    предст_пр = поле(d, "представитель_предприятия",
                     "Соглашение: представитель предприятия (в лице кого)",
                     недомеры)
    предст_рцк = поле(d, "представитель_рцк",
                      "Соглашение: представитель РЦК (в лице кого)", недомеры)
    осн_рцк = поле(d, "основание_рцк",
                   "Соглашение: основание полномочий представителя РЦК",
                   недомеры)
    преамбула = (
        f"{пр} (далее – Предприятие) в лице {предст_пр}, действующего на "
        f"основании устава, с одной стороны, и {рцк} (далее – РЦК) в лице "
        f"{предст_рцк}, действующего на основании {осн_рцк}, с другой "
        f"стороны, совместно именуемые Стороны, руководствуясь взаимной "
        f"заинтересованностью в реализации национального проекта "
        f"«Производительность труда» (далее – Национальный проект), в принятии "
        f"мер и проведении мероприятий, обеспечивающих максимальное повышение "
        f"производительности труда на Предприятии, заключили настоящее "
        f"Соглашение о сотрудничестве (далее – Соглашение) о нижеследующем.")

    штраф_отч = (d.get("штраф_отчетность") or "").strip()
    if not штраф_отч:
        штраф_отч = ПУСТО
        недомеры.append("Соглашение п. 2.2.10: штраф за непредоставление "
                        "отчетных материалов, руб. (цифрами и прописью)")
    штраф_раст = (d.get("штраф_расторжение") or "").strip()
    if not штраф_раст:
        штраф_раст = ПУСТО
        недомеры.append("Соглашение п. 9.8: штраф при досрочном расторжении "
                        "по инициативе Предприятия, руб. (цифрой и прописью)")

    замены = {
        # преамбула — заменяем целиком по уникальному признаку
        "ПРЕАМБУЛА": преамбула,
    }
    # подстановки-подстроки (внутри более длинных абзацев шаблона)
    подстроки = [
        ("Соглашение о сотрудничестве № _______",
         f"Соглашение о сотрудничестве № {номер}"),
        ("в виде штрафа в размере цифрами (прописью) рублей",
         f"в виде штрафа в размере {штраф_отч} рублей"),
        ("цифрой (прописью) рублей 00 копеек",
         f"{штраф_раст} рублей 00 копеек"),
    ]

    def уведомления_замены():
        out = {}
        if уп.get("адрес"):
            out["По адресу:"] = "По адресу: " + уп["адрес"]
        else:
            недомеры.append("Уведомления Предприятия: адрес")
            out["По адресу:"] = "По адресу: " + ПУСТО
        out["По телефону:"] = "По телефону: " + (уп.get("телефон") or ПУСТО)
        out["По электронной почте:"] = ("По электронной почте: "
                                        + (уп.get("почта") or ПУСТО))
        if not уп.get("телефон"):
            недомеры.append("Уведомления Предприятия: телефон")
        if not уп.get("почта"):
            недомеры.append("Уведомления Предприятия: электронная почта")
        out["По адресу: адрес"] = "По адресу: " + (уц.get("адрес") or ПУСТО)
        out["По телефону: телефон"] = ("По телефону: "
                                       + (уц.get("телефон") or ПУСТО))
        out["Канал для корреспонденции: электронная почта"] = (
            "Канал для корреспонденции: " + (уц.get("почта") or ПУСТО))
        if not уц.get("адрес"):
            недомеры.append("Уведомления РЦК: адрес")
        if not уц.get("телефон"):
            недомеры.append("Уведомления РЦК: телефон")
        if not уц.get("почта"):
            недомеры.append("Уведомления РЦК: электронная почта")
        return out

    замены.update(уведомления_замены())

    # реквизиты (раздел 10): «Уполномоченное лицо:» встречается дважды —
    # решается очередью; остальные строки уникальны по префиксу значения.
    рек_замены = {
        "Полное фирменное наименование:":
            "Полное фирменное наименование: "
            + (рп.get("наименование") or d.get("предприятие") or ПУСТО),
        "Телефон приемной:":
            "Телефон приемной: " + (рп.get("телефон") or ПУСТО),
        "E-mail приемной:":
            "E-mail приемной: " + (рп.get("почта") or ПУСТО),
        "Официальный сайт в сети Интернет:":
            "Официальный сайт в сети Интернет: " + (рп.get("сайт") or ПУСТО),
        "ИНН / КПП:":
            "ИНН / КПП: " + (рп.get("инн_кпп") or ПУСТО),
        "ОКПО:":
            "ОКПО: " + (рп.get("окпо") or ПУСТО),
        "Полное наименование:":
            "Полное наименование: "
            + (рц.get("наименование") or d.get("рцк") or ПУСТО),
        "Телефон:":
            "Телефон: " + (рц.get("телефон") or ПУСТО),
        "E-mail:":
            "E-mail: " + (рц.get("почта") or ПУСТО),
        "ИНН / КПП: 7724426759 / 770301001":
            "ИНН / КПП: " + (рц.get("инн_кпп") or "7724426759 / 770301001"),
        "ОКПО: 22132742":
            "ОКПО: " + (рц.get("окпо") or "22132742"),
    }
    замены.update(рек_замены)
    for метка, словарь, поля in (
            ("Реквизиты Предприятия", рп,
             ("наименование", "адрес", "телефон", "почта", "сайт",
              "инн_кпп", "окпо")),
            ("Реквизиты РЦК", рц, ("адрес", "телефон", "почта"))):
        for п in поля:
            if п == "наименование" and (рп.get("наименование") or
                                        d.get("предприятие")):
                continue
            if not (словарь.get(п) or "").strip():
                недомеры.append(f"{метка}: {п}")
    # «Место нахождения:» дважды (10.1 и 10.2) — очередь
    места = [рп.get("адрес") or ПУСТО, рц.get("адрес") or ПУСТО]
    # «Уполномоченное лицо:» дважды (5.1.1 и 5.1.2) — очередь
    лица = [уп.get("лицо") or ПУСТО, уц.get("лицо") or ПУСТО]
    if not уп.get("лицо"):
        недомеры.append("Уведомления Предприятия: уполномоченное лицо")
    if not уц.get("лицо"):
        недомеры.append("Уведомления РЦК: уполномоченное лицо")
    return замены, подстроки, места, лица


def build_soglashenie(d, путь_выход):
    """Соглашение о сотрудничестве (ред. 8): основной текст разделов 1–12
    дословно по шаблону + подстановка реквизитов; приложения № 1–8
    формируются отдельными документами."""
    if not isinstance(d, dict):
        raise ValueError("Корень вход-JSON должен быть объектом")
    недомеры = []
    замены, подстроки, места, лица = _подстановки(d, недомеры)
    подп = d.get("подписанты") or {}
    пп, пц = подп.get("предприятие") or {}, подп.get("рцк") or {}
    if not (пп.get("фио") or "").strip():
        недомеры.append("Подписант от Предприятия: ФИО")
    if not (пц.get("фио") or "").strip():
        недомеры.append("Подписант от РЦК: ФИО")

    doc = _новый_документ()
    очередь_мест = list(места)
    очередь_лиц = list(лица)
    for kind, payload in СКЕЛЕТ_СОГЛАШЕНИЕ:
        if kind == "p":
            текст = payload
            стр = текст.strip()
            if стр in замены:
                текст = замены[стр]
            elif "(далее – Предприятие) в лице" in текст and                     "заключили настоящее" in текст:
                текст = замены["ПРЕАМБУЛА"]
            elif стр == "Место нахождения:":
                текст = "Место нахождения: " + (очередь_мест.pop(0)
                                               if очередь_мест else ПУСТО)
            elif стр == "Уполномоченное лицо:":
                текст = "Уполномоченное лицо: " + (очередь_лиц.pop(0)
                                                   if очередь_лиц else ПУСТО)
            else:
                for старое, новое in подстроки:
                    if старое in текст:
                        текст = текст.replace(старое, новое)
            bold = стр.startswith(("Соглашение о сотрудничестве",
                                   "1. Предмет", "2. Условия", "3. Протокол",
                                   "4. Конфиденциальность", "5.Уведомления",
                                   "5. Уведомления", "6. Противодействие",
                                   "7. Заверения", "8. Обстоятельства",
                                   "9. Заключительные", "10. Адреса",
                                   "11. Приложения", "12. Подписи"))
            if стр:
                параграф(doc, текст, bold=bold, size=10 if not bold else 11,
                         space_after=4)
        else:
            rows = payload
            t = таблица(doc, len(rows), max(len(r) for r in rows), границы=False)
            _снять_границы(t)
            for ri, row in enumerate(rows):
                for ci, val in enumerate(row):
                    if ci >= len(t.rows[ri].cells):
                        continue
                    v = val
                    if v.strip() == "место подписания":
                        v = (d.get("место") or "").strip() or ПУСТО
                        if v == ПУСТО:
                            недомеры.append("Соглашение: место подписания")
                    elif v.strip().startswith("«__» ___________ 20__ г."):
                        v = (d.get("дата") or "").strip() or ПУСТО
                        if v == ПУСТО:
                            недомеры.append("Соглашение: дата подписания")
                    elif "от Предприятия:" in v:
                        v = "от Предприятия:"
                    elif v.startswith("_____________________ /") and ri > 0:
                        # строка подписи: колонка 0 — предприятие, 1 — РЦК
                        фио = (пп.get("фио") if ci == 0 else пц.get("фио")) or "___"
                        v = f"_____________________ /{фио}/\nМ.П."
                    ячейка(t.rows[ri].cells[ci], v,
                           bold=("от " in v or "Подписи" in v), size=10)
    _раздел_домерить(doc, недомеры)
    doc.save(путь_выход)
    return {"незаполненных_полей": len(set(недомеры)), "путь": путь_выход}


# ---------------------------------------------------------------------------
# отчёты и итоги прогонов (для реестра инструментов)
# ---------------------------------------------------------------------------

def отчёт_akt_md(d, итог):
    вар = "ФЦК ↔ Предприятие" if (d.get("вариант") or "рцк") == "фцк"         else "РЦК ↔ Предприятие"
    L = ["# Акт начала мероприятий (Приложение № 7 к Соглашению)", ""]
    L.append(f"**Вариант:** {вар}")
    L.append(f"**Предприятие:** {d.get('предприятие') or '___'}")
    L.append(f"**Дата начала мероприятий:** {d.get('дата_начала') or '___'}")
    L.append(f"**Незаполненных полей:** {итог['незаполненных_полей']}")
    L.append("")
    L.append("Файл docx сохранён в истории прогона (immutable).")
    return "\n".join(L)


def отчёт_soglashenie_md(d, итог):
    L = ["# Соглашение о сотрудничестве (рекомендованная форма, ред. 8)", ""]
    L.append(f"**№:** {d.get('номер') or '___'} · **дата:** {d.get('дата') or '___'}")
    L.append(f"**Предприятие:** {d.get('предприятие') or '___'}")
    L.append(f"**РЦК:** {d.get('рцк') or '___'}")
    L.append(f"**Незаполненных полей:** {итог['незаполненных_полей']}")
    L.append("")
    L.append("Основной текст разделов 1–12 по шаблону; приложения № 1–8 "
             "формируются отдельно (прил. № 6 — «Протокол закрытия», "
             "прил. № 7 — «Акт начала мероприятий»).")
    return "\n".join(L)


def итоги_akt(d, итог):
    return {"документ": "акт_начала",
            "вариант": (d.get("вариант") or "рцк"),
            "предприятие": d.get("предприятие") or None,
            "дата_начала": d.get("дата_начала") or None,
            "незаполненных_полей": итог["незаполненных_полей"]}


def итоги_soglashenie(d, итог):
    return {"документ": "соглашение",
            "номер": d.get("номер") or None,
            "предприятие": d.get("предприятие") or None,
            "рцк": d.get("рцк") or None,
            "незаполненных_полей": итог["незаполненных_полей"]}


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def main(argv):
    if len(argv) < 3:
        print(__doc__)
        return 2
    вид, вход = argv[1], argv[2]
    выход = argv[3] if len(argv) > 3 else (
        "акт_начала.docx" if вид == "акт" else "соглашение.docx")
    with open(вход, encoding="utf-8") as f:
        данные = json.load(f)
    if вид == "акт":
        итог = build_akt(данные, выход)
    elif вид == "соглашение":
        итог = build_soglashenie(данные, выход)
    else:
        print("вид: акт | соглашение")
        return 2
    print(json.dumps(итог, ensure_ascii=False, indent=1))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
